image_search:
/**
 * image_search: the Kortix image search tool (Serper Google Images). Kortix
 * maintains this file. A project lists it in kortix.yaml as
 * `image_search: kortix:image_search`. `kortix tools eject image_search`
 * copies it to `tools/image_search.ts` for the project to own and change; the
 * copy runs unchanged on every harness.
 *
 * A call goes to the Kortix API's billed router proxy with the session token
 * (`KORTIX_API_URL`, `KORTIX_TOKEN`); the router holds the Serper key. A box
 * with no Kortix API calls Serper itself with `SERPER_API_KEY`.
 *
 * The web UI renders a call from the output JSON. A changed copy must keep
 * that shape, or the UI shows the raw output.
 */

/** What a call receives (the project tool contract): the session env, secrets included, and the turn's abort signal. */
interface ToolContext {
  env: Record<string, string | undefined>
  signal?: AbortSignal
}

const TIMEOUT_MS = 60_000

/** The Kortix router proxy and the session token, or Serper and the project's own key. */
function upstream(env: ToolContext['env']): { base: string; key: string } {
  const api = env.KORTIX_API_URL?.trim().replace(/\/+$/, '')
  if (api) {
    const token = env.KORTIX_TOKEN?.trim()
    if (!token) throw new Error('KORTIX_TOKEN is not set.')
    return { base: `${api.endsWith('/v1') ? api : `${api}/v1`}/router/serper`, key: token }
  }
  const key = env.SERPER_API_KEY?.trim()
  if (!key) throw new Error('SERPER_API_KEY is not set.')
  return { base: 'https://google.serper.dev', key }
}

type SerperResponse = { images?: Array<{ imageUrl: string; title?: string; link?: string; imageWidth?: number; imageHeight?: number }> }

function serperImages(query: string, data: SerperResponse) {
  const images = (data.images ?? []).map((image) => ({
    url: image.imageUrl,
    title: image.title ?? '',
    source: image.link ?? '',
    width: image.imageWidth ?? 0,
    height: image.imageHeight ?? 0,
  }))
  return { query, total: images.length, images }
}

export default {
  description:
    'Search for images using the Serper Google Images API. ' +
    'Returns image URLs with titles, source pages, and dimensions. ' +
    'Supports batch queries separated by |||. ' +
    'Use specific descriptive queries including topic/brand names for best results.',
  parameters: {
    type: 'object',
    properties: {
      query: { type: 'string', description: "Image search query. For batch, separate with ||| (e.g. 'cats ||| dogs')" },
      num_results: { type: 'number', description: 'Images per query (1-100). Default: 12' },
    },
    required: ['query'],
  },
  async execute(args: Record<string, any>, { env, signal }: ToolContext): Promise<string> {
    const { base, key } = upstream(env)
    const queries = String(args.query ?? '').split('|||').map((query) => query.trim()).filter(Boolean)
    if (queries.length === 0) throw new Error('The query is empty.')
    const num = Math.max(1, Math.min(args.num_results ?? 12, 100))
    const payload = queries.map((q) => ({ q, num }))
    const response = await fetch(`${base}/images`, {
      method: 'POST',
      headers: { 'X-API-KEY': key, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload.length === 1 ? payload[0] : payload),
      signal: signal ? AbortSignal.any([signal, AbortSignal.timeout(TIMEOUT_MS)]) : AbortSignal.timeout(TIMEOUT_MS),
    })
    if (!response.ok) throw new Error(`Serper API returned ${response.status}: ${await response.text()}`)
    const data = (await response.json()) as SerperResponse | SerperResponse[]
    if (queries.length > 1) {
      const all = Array.isArray(data) ? data : [data]
      return JSON.stringify({ batch_mode: true, results: all.map((entry, i) => serperImages(queries[i]!, entry)) }, null, 2)
    }
    const single = serperImages(queries[0]!, Array.isArray(data) ? (data[0] ?? {}) : data)
    return single.total === 0 ? `No images found for: '${queries[0]}'` : JSON.stringify(single, null, 2)
  },
}

memory:
/**
 * memory: the Kortix memory tool. Kortix maintains this file. A project lists
 * it in kortix.yaml as `memory: kortix:memory`. `kortix tools eject memory`
 * copies it to `tools/memory.ts` for the project to own and change; the copy
 * runs unchanged on every harness. The web UI renders a call from its
 * arguments (`command`, `path`); a changed copy must keep them.
 *
 * A 1:1 port of Anthropic's `memory_20250818` tool, rooted at the project's
 * `memory/` folder: six commands (view / create / str_replace / insert /
 * delete / rename) and the return strings the model is trained to read. A
 * refused command is a returned string, not a thrown error, as in the
 * reference backend.
 *
 * Every write is an ordinary file change under `memory/`, so memory edits
 * reach `main` through the normal change-request flow.
 *
 * Security (ported from the hardened SDK source):
 *  - the path boundary check uses a trailing separator, so a sibling directory
 *    such as `memory-evil` cannot pass as the root (CVE-2026-34451);
 *  - the symlink check walks to the deepest existing ancestor and verifies its
 *    real path stays inside the root;
 *  - files are created 0o600 and directories 0o700 (CVE-2026-41686);
 *  - writes are atomic (temp file, fsync, rename).
 */
import { randomUUID } from 'node:crypto'
import * as fs from 'node:fs/promises'
import * as path from 'node:path'

/** What a call receives (the project tool contract): `directory` is the project checkout. */
interface ToolContext {
  directory: string
}

/** Repo-relative root every memory path must live under. */
const MEMORY_PREFIX = 'memory'

// Owner read/write only — Node's default 0o666 would be world-readable
// under a permissive umask (common in Docker base images).
const FILE_CREATE_MODE = 0o600
// fs.mkdir defaults to 0o777; lock memory dirs down the same way.
const DIR_CREATE_MODE = 0o700

const MAX_LINES = 999999
const LINE_NUMBER_WIDTH = String(MAX_LINES).length // 6

// ── helpers ──────────────────────────────────────────────────────────────

async function exists(p: string): Promise<boolean> {
  return fs
    .access(p)
    .then(() => true)
    .catch((err: NodeJS.ErrnoException) => {
      if (err.code === 'ENOENT') return false
      throw err
    })
}

/**
 * fsync a directory so a newly created / renamed / removed entry is durable.
 *
 * This is the load-bearing half of 'create actually persisted': fsync-ing a
 * file only flushes its *contents* — the directory entry (the filename) lives
 * in the parent directory's metadata and is only guaranteed on disk after the
 * directory itself is fsynced. Without this, `create` can return success and
 * still vanish if the sandbox is snapshotted or killed before the dirent hits
 * disk. Best-effort: some platforms/filesystems (notably Windows) reject
 * fsync on a directory handle — those errors are non-fatal and ignored.
 */
async function fsyncDir(dirPath: string): Promise<void> {
  let handle: fs.FileHandle | undefined
  try {
    handle = await fs.open(dirPath, 'r')
    await handle.sync()
  } catch (err: any) {
    // EISDIR/EINVAL/EPERM/EACCES: platform can't fsync a dir handle — fine.
    if (!['EISDIR', 'EINVAL', 'EPERM', 'EACCES', 'ENOTSUP'].includes(err?.code)) {
      throw err
    }
  } finally {
    await handle?.close().catch(() => {})
  }
}

function formatFileSize(bytes: number): string {
  if (bytes === 0) return '0B'
  const k = 1024
  const sizes = ['B', 'K', 'M', 'G']
  const i = Math.floor(Math.log(bytes) / Math.log(k))
  const size = bytes / Math.pow(k, i)
  return (size % 1 === 0 ? size.toString() : size.toFixed(1)) + sizes[i]
}

/**
 * Write atomically: temp file (0o600) → fsync → rename. A crash mid-write
 * leaves either the complete old content or the complete new content.
 */
async function atomicWriteFile(targetPath: string, content: string): Promise<void> {
  const dir = path.dirname(targetPath)
  const tempPath = path.join(dir, `.tmp-${process.pid}-${randomUUID()}`)
  let handle: fs.FileHandle | undefined
  try {
    handle = await fs.open(tempPath, 'wx', FILE_CREATE_MODE)
    await handle.writeFile(content, 'utf-8')
    await handle.sync()
    await handle.close()
    handle = undefined
    await fs.rename(tempPath, targetPath)
    // Persist the rename itself: the new dirent isn't durable until the
    // containing directory is fsynced.
    await fsyncDir(dir)
  } catch (err) {
    if (handle) await handle.close().catch(() => {})
    await fs.unlink(tempPath).catch(() => {})
    throw err
  }
}

/**
 * Reject paths that escape the memory root through a symlink. Walks up from
 * the target to the deepest existing ancestor, realpath-resolves it, and
 * verifies the real path is still inside the root.
 */
async function validateNoSymlinkEscape(targetPath: string, memoryRoot: string): Promise<void> {
  const resolvedRoot = await fs.realpath(memoryRoot)
  let current = targetPath
  while (true) {
    try {
      const resolved = await fs.realpath(current)
      if (resolved !== resolvedRoot && !resolved.startsWith(resolvedRoot + path.sep)) {
        throw new Error(`Path would escape ${MEMORY_PREFIX} directory via symlink`)
      }
      return
    } catch (err: any) {
      if (err.code !== 'ENOENT') throw err
      const parent = path.dirname(current)
      if (parent === current || current === memoryRoot) return
      current = parent
    }
  }
}

async function readFileContent(fullPath: string, memoryPath: string): Promise<string> {
  try {
    return await fs.readFile(fullPath, 'utf-8')
  } catch (err: any) {
    if (err.code === 'ENOENT') {
      throw new Error(
        `The file ${memoryPath} no longer exists (may have been deleted or renamed concurrently).`,
      )
    }
    throw err
  }
}

/** Resolve & sandbox a repo-relative memory path to an absolute path. */
async function validatePath(memoryPath: string, projectDir: string): Promise<string> {
  const root = path.resolve(projectDir, MEMORY_PREFIX)
  // Normalize a leading './' so both 'memory' and './memory' work.
  const cleaned = memoryPath.replace(/^\.\//, '')
  if (cleaned !== MEMORY_PREFIX && !cleaned.startsWith(MEMORY_PREFIX + '/')) {
    throw new Error(`Path must start with ${MEMORY_PREFIX}, got: ${memoryPath}`)
  }

  const resolved = path.resolve(projectDir, cleaned)
  // Trailing separator is load-bearing: without it, a sibling dir like
  // 'memory-evil' would pass the prefix check.
  if (resolved !== root && !resolved.startsWith(root + path.sep)) {
    throw new Error(`Path ${memoryPath} would escape ${MEMORY_PREFIX} directory`)
  }

  await fs.mkdir(root, { recursive: true, mode: DIR_CREATE_MODE })
  await validateNoSymlinkEscape(resolved, root)
  return resolved
}

// ── command handlers ─────────────────────────────────────────────────────

async function view(memoryPath: string, viewRange: number[] | undefined, dir: string): Promise<string> {
  const fullPath = await validatePath(memoryPath, dir)

  let stat
  try {
    stat = await fs.stat(fullPath)
  } catch (err: any) {
    if (err.code === 'ENOENT')
      return `The path ${memoryPath} does not exist. Please provide a valid path.`
    throw err
  }

  if (stat.isDirectory()) {
    const items: Array<{ size: string; path: string }> = []
    const collect = async (dirPath: string, rel: string, depth: number): Promise<void> => {
      if (depth > 2) return
      for (const item of (await fs.readdir(dirPath)).sort()) {
        if (item.startsWith('.') || item === 'node_modules') continue
        const itemPath = path.join(dirPath, item)
        const itemRel = rel ? `${rel}/${item}` : item
        let s
        try {
          s = await fs.stat(itemPath)
        } catch {
          continue
        }
        if (s.isDirectory()) {
          items.push({ size: formatFileSize(s.size), path: `${itemRel}/` })
          if (depth < 2) await collect(itemPath, itemRel, depth + 1)
        } else if (s.isFile()) {
          items.push({ size: formatFileSize(s.size), path: itemRel })
        }
      }
    }
    await collect(fullPath, '', 1)

    const header = `Here're the files and directories up to 2 levels deep in ${memoryPath}, excluding hidden items and node_modules:`
    const lines = [
      `${formatFileSize(stat.size)}\t${memoryPath}`,
      ...items.map((it) => `${it.size}\t${memoryPath}/${it.path}`),
    ]
    return `${header}\n${lines.join('\n')}`
  }

  if (stat.isFile()) {
    const content = await readFileContent(fullPath, memoryPath)
    const allLines = content.split('\n')
    if (allLines.length > MAX_LINES) {
      return `File ${memoryPath} has too many lines (${allLines.length}). Maximum is ${MAX_LINES.toLocaleString()} lines.`
    }
    let display = allLines
    let startNum = 1
    if (viewRange && viewRange.length === 2) {
      const start = Math.max(1, viewRange[0]!) - 1
      const end = viewRange[1] === -1 ? allLines.length : viewRange[1]
      display = allLines.slice(start, end)
      startNum = start + 1
    }
    const numbered = display.map(
      (line, i) => `${String(i + startNum).padStart(LINE_NUMBER_WIDTH, ' ')}\t${line}`,
    )
    return `Here's the content of ${memoryPath} with line numbers:\n${numbered.join('\n')}`
  }

  return `Unsupported file type for ${memoryPath}`
}

async function create(memoryPath: string, fileText: string, dir: string): Promise<string> {
  const fullPath = await validatePath(memoryPath, dir)
  const parent = path.dirname(fullPath)
  await fs.mkdir(parent, { recursive: true, mode: DIR_CREATE_MODE })
  let handle: fs.FileHandle | undefined
  try {
    // 'wx' atomically claims a fresh name (no truncation of an existing file).
    handle = await fs.open(fullPath, 'wx', FILE_CREATE_MODE)
    await handle.writeFile(fileText, 'utf-8')
    await handle.sync()
    await handle.close()
    handle = undefined
  } catch (err: any) {
    if (err?.code === 'EEXIST') return `Error: File ${memoryPath} already exists`
    throw err
  } finally {
    await handle?.close().catch(() => {})
  }
  // Without this, the file's *contents* are flushed but its directory entry
  // may not be — so a create can report success yet not survive a snapshot.
  await fsyncDir(parent)
  return `File created successfully at: ${memoryPath}`
}

async function strReplace(
  memoryPath: string,
  oldStr: string,
  newStr: string,
  dir: string,
): Promise<string> {
  const fullPath = await validatePath(memoryPath, dir)
  let stat
  try {
    stat = await fs.stat(fullPath)
  } catch (err: any) {
    if (err.code === 'ENOENT')
      return `Error: The path ${memoryPath} does not exist. Please provide a valid path.`
    throw err
  }
  if (!stat.isFile()) return `Error: The path ${memoryPath} is not a file.`

  const content = await readFileContent(fullPath, memoryPath)
  const lines = content.split('\n')
  const matching: number[] = []
  lines.forEach((line, i) => {
    if (line.includes(oldStr)) matching.push(i + 1)
  })

  if (matching.length === 0) {
    return `No replacement was performed, old_str \`${oldStr}\` did not appear verbatim in ${memoryPath}.`
  }
  if (matching.length > 1) {
    return `No replacement was performed. Multiple occurrences of old_str \`${oldStr}\` in lines: ${matching.join(', ')}. Please ensure it is unique`
  }

  const newContent = content.replace(oldStr, newStr)
  await atomicWriteFile(fullPath, newContent)

  const newLines = newContent.split('\n')
  const changed = matching[0]! - 1
  const from = Math.max(0, changed - 2)
  const to = Math.min(newLines.length, changed + 3)
  const snippet = newLines
    .slice(from, to)
    .map((line, i) => `${String(from + i + 1).padStart(LINE_NUMBER_WIDTH, ' ')}\t${line}`)
  return `The memory file has been edited. Here is the snippet showing the change (with line numbers):\n${snippet.join('\n')}`
}

async function insert(
  memoryPath: string,
  insertLine: number,
  insertText: string,
  dir: string,
): Promise<string> {
  const fullPath = await validatePath(memoryPath, dir)
  let stat
  try {
    stat = await fs.stat(fullPath)
  } catch (err: any) {
    if (err.code === 'ENOENT')
      return `Error: The path ${memoryPath} does not exist. Please provide a valid path.`
    throw err
  }
  if (!stat.isFile()) return `Error: The path ${memoryPath} is not a file.`

  const content = await readFileContent(fullPath, memoryPath)
  const lines = content.split('\n')
  if (insertLine < 0 || insertLine > lines.length) {
    return `Error: Invalid \`insert_line\` parameter: ${insertLine}. It should be within the range of lines of the file: [0, ${lines.length}]`
  }
  lines.splice(insertLine, 0, insertText.replace(/\n$/, ''))
  await atomicWriteFile(fullPath, lines.join('\n'))
  return `The file ${memoryPath} has been edited.`
}

async function del(memoryPath: string, dir: string): Promise<string> {
  const fullPath = await validatePath(memoryPath, dir)
  const cleaned = memoryPath.replace(/^\.\//, '')
  if (cleaned === MEMORY_PREFIX) return `Cannot delete the ${MEMORY_PREFIX} directory itself`
  try {
    await fs.rm(fullPath, { recursive: true, force: false })
  } catch (err: any) {
    if (err.code === 'ENOENT') return `Error: The path ${memoryPath} does not exist`
    throw err
  }
  await fsyncDir(path.dirname(fullPath))
  return `Successfully deleted ${memoryPath}`
}

async function rename(oldPath: string, newPath: string, dir: string): Promise<string> {
  const oldFull = await validatePath(oldPath, dir)
  const newFull = await validatePath(newPath, dir)
  // POSIX rename() silently overwrites; best-effort guard.
  if (await exists(newFull)) return `Error: The destination ${newPath} already exists`
  const newParent = path.dirname(newFull)
  await fs.mkdir(newParent, { recursive: true, mode: DIR_CREATE_MODE })
  try {
    await fs.rename(oldFull, newFull)
  } catch (err: any) {
    if (err.code === 'ENOENT') return `Error: The path ${oldPath} does not exist`
    throw err
  }
  // Persist both sides of the move (the entry left one dir and entered another).
  await fsyncDir(newParent)
  await fsyncDir(path.dirname(oldFull))
  return `Successfully renamed ${oldPath} to ${newPath}`
}

/** Every memory path resolves under `<dir>/memory`; `dir` is the project checkout. */
async function run(args: Record<string, any>, dir: string): Promise<string> {
  const need = (...names: string[]) => names.find((name) => args[name] === undefined || (name.endsWith('path') && !args[name]))
  const missing = (name: string) => `Error: \`${name}\` is required for ${args.command}.`
  let absent: string | undefined
  switch (args.command) {
    case 'view':
      return (absent = need('path')) ? missing(absent) : view(args.path, args.view_range, dir)
    case 'create':
      return (absent = need('path', 'file_text')) ? missing(absent) : create(args.path, args.file_text, dir)
    case 'str_replace':
      return (absent = need('path', 'old_str', 'new_str')) ? missing(absent) : strReplace(args.path, args.old_str, args.new_str, dir)
    case 'insert':
      return (absent = need('path', 'insert_line', 'insert_text')) ? missing(absent) : insert(args.path, args.insert_line, args.insert_text, dir)
    case 'delete':
      return (absent = need('path')) ? missing(absent) : del(args.path, dir)
    case 'rename':
      return (absent = need('old_path', 'new_path')) ? missing(absent) : rename(args.old_path, args.new_path, dir)
    default:
      return 'Error: unknown command'
  }
}

export default {
  description:
    'Persistent project memory — read, write, and curate the project brain in `memory/`. ' +
    'This is the canonical way to work with memory; use it instead of the generic read/edit/write tools for anything under `memory/`. ' +
    'Memory persists across sessions and is shared with the whole team via the repo, so write durable facts here. ' +
    'ALWAYS `view` `memory` before starting a task to recover prior context, and record durable progress as you go — your context window may reset at any time.\n\n' +
    'Paths are repo-relative and MUST start with `memory` (e.g. `memory/overview.md`). ' +
    "Keep memory coherent and organized: prefer editing existing files, rename or delete stale ones, and don't create new files unless a topic deserves its own page. " +
    'Always keep `memory/MEMORY.md` (the index) in sync — one line per sub-file. ' +
    'Never store secrets, tokens, or PII. Edits land on `main` through the normal change-request flow.\n\n' +
    'Commands: `view` (dir listing or file with line numbers; optional view_range), `create` (new file), ' +
    '`str_replace` (replace a unique snippet), `insert` (insert at a line), `delete` (remove file/dir), `rename` (move file/dir).',
  parameters: {
    type: 'object',
    properties: {
      command: { type: 'string', enum: ['view', 'create', 'str_replace', 'insert', 'delete', 'rename'], description: 'The memory operation to perform.' },
      path: { type: 'string', description: 'Repo-relative path under `memory` (e.g. `memory/overview.md`). Required for view, create, str_replace, insert, delete.' },
      view_range: { type: 'array', items: { type: 'number' }, description: 'Optional [start, end] line range for `view` of a file. Use -1 for end-of-file.' },
      file_text: { type: 'string', description: 'File contents. Required for `create`.' },
      old_str: { type: 'string', description: 'Exact text to replace (must be unique in the file). Required for `str_replace`.' },
      new_str: { type: 'string', description: 'Replacement text. Required for `str_replace` (use empty string to delete).' },
      insert_line: { type: 'number', description: 'Line number to insert after (0 = top of file). Required for `insert`.' },
      insert_text: { type: 'string', description: 'Text to insert. Required for `insert`.' },
      old_path: { type: 'string', description: 'Source path. Required for `rename`.' },
      new_path: { type: 'string', description: 'Destination path. Required for `rename`.' },
    },
    required: ['command'],
  },
  execute: (args: Record<string, any>, { directory }: ToolContext): Promise<string> =>
    run(args, directory).catch((err) => `Error: ${err?.message ?? String(err)}`),
}

scrape_webpage:
/**
 * scrape_webpage: the Kortix page scraper (Firecrawl). Kortix maintains this
 * file. A project lists it in kortix.yaml as
 * `scrape_webpage: kortix:scrape_webpage`. `kortix tools eject scrape_webpage`
 * copies it to `tools/scrape_webpage.ts` for the project to own and change;
 * the copy runs unchanged on every harness.
 *
 * A call goes to the Kortix API's billed router proxy with the session token
 * (`KORTIX_API_URL`, `KORTIX_TOKEN`); the router holds the Firecrawl key. A
 * box with no Kortix API calls Firecrawl itself with `FIRECRAWL_API_KEY`.
 *
 * The web UI renders a call from the output JSON. A changed copy must keep
 * that shape, or the UI shows the raw output.
 */

/** What a call receives (the project tool contract): the session env, secrets included, and the turn's abort signal. */
interface ToolContext {
  env: Record<string, string | undefined>
  signal?: AbortSignal
}

const TIMEOUT_MS = 35_000
const RETRIES = 3

/** The Kortix router proxy and the session token, or Firecrawl and the project's own key. */
function upstream(env: ToolContext['env']): { base: string; key: string } {
  const api = env.KORTIX_API_URL?.trim().replace(/\/+$/, '')
  if (api) {
    const token = env.KORTIX_TOKEN?.trim()
    if (!token) throw new Error('KORTIX_TOKEN is not set.')
    return { base: `${api.endsWith('/v1') ? api : `${api}/v1`}/router/firecrawl`, key: token }
  }
  const key = env.FIRECRAWL_API_KEY?.trim()
  if (!key) throw new Error('FIRECRAWL_API_KEY is not set.')
  return { base: 'https://api.firecrawl.dev', key }
}

type ScrapeResult = {
  url: string
  success: boolean
  title?: string
  content?: string
  content_length?: number
  html?: string
  metadata?: Record<string, unknown>
  error?: string
}

async function scrapeOne(base: string, key: string, url: string, includeHtml: boolean, signal?: AbortSignal): Promise<ScrapeResult> {
  for (let attempt = 1; ; attempt++) {
    try {
      const response = await fetch(`${base}/v2/scrape`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ url, formats: includeHtml ? ['markdown', 'html'] : ['markdown'], timeout: 30000 }),
        signal: signal ? AbortSignal.any([signal, AbortSignal.timeout(TIMEOUT_MS)]) : AbortSignal.timeout(TIMEOUT_MS),
      })
      const raw = await response.text()
      const body = JSON.parse(raw) as { success?: boolean; data?: Record<string, unknown>; error?: string }
      if (!response.ok || !body.success) throw new Error(body.error || `${response.status} Error: ${raw}`)
      const data = body.data ?? {}
      const metadata = (data.metadata ?? {}) as Record<string, string>
      const markdown = (data.markdown ?? '') as string
      const html = (data.html ?? '') as string
      return {
        url,
        success: true,
        title: metadata.title ?? '',
        content: markdown,
        content_length: markdown.length,
        ...(includeHtml && html ? { html } : {}),
        ...(Object.keys(metadata).length > 0 ? { metadata } : {}),
      }
    } catch (err) {
      const reason = err instanceof Error ? err.message : String(err)
      // Only a timeout is worth a second request; an aborted turn is not.
      if (/timeout/i.test(reason) && attempt < RETRIES && !signal?.aborted) {
        await new Promise((resolve) => setTimeout(resolve, 2 ** attempt * 1000))
        continue
      }
      return { url, success: false, error: reason }
    }
  }
}

export default {
  description:
    'Fetch and extract content from web pages using Firecrawl. ' +
    'Converts HTML to clean markdown. ' +
    'Supports multiple URLs separated by commas. ' +
    'Batch URLs in a single call for efficiency. ' +
    'For GitHub URLs, prefer gh CLI via Bash instead.',
  parameters: {
    type: 'object',
    properties: {
      urls: { type: 'string', description: "URLs to scrape, comma-separated (e.g. 'https://example.com/a,https://example.com/b')" },
      include_html: { type: 'boolean', description: 'Include raw HTML alongside markdown. Default: false' },
    },
    required: ['urls'],
  },
  async execute(args: Record<string, any>, { env, signal }: ToolContext): Promise<string> {
    const { base, key } = upstream(env)
    const urls = String(args.urls ?? '').split(',').map((url) => url.trim()).filter(Boolean)
    if (urls.length === 0) throw new Error('No valid URLs provided.')
    const results = await Promise.all(urls.map((url) => scrapeOne(base, key, url, args.include_html ?? false, signal)))
    const successful = results.filter((result) => result.success).length
    if (successful === 0) {
      throw new Error(`Failed to scrape all ${results.length} URLs. ${results.map((r) => `${r.url}: ${r.error}`).join('; ')}`)
    }
    if (results.length === 1) return JSON.stringify(results[0], null, 2)
    return JSON.stringify({ total: results.length, successful, failed: results.length - successful, results }, null, 2)
  },
}

show:
/**
 * show: the Kortix tool that presents an existing output (a file, an image, a
 * URL, inline text) to the user. Kortix maintains this file. A project lists
 * it in kortix.yaml as `show: kortix:show`. `kortix tools eject show` copies
 * it to `tools/show.ts` for the project to own and change; the copy runs
 * unchanged on every harness.
 *
 * The web UI renders a `show` call from its arguments (`type`, `path`, `url`,
 * `content`, `items`). A changed copy must keep those arguments. A relative
 * `path` resolves against the project checkout.
 */
import { existsSync } from 'node:fs'
import { resolve } from 'node:path'

/** What a call receives (the project tool contract): `directory` is the project checkout. */
interface ToolContext {
  directory: string
}

/** Content types the show tool can present. */
const TYPES = [
  'file',
  'image',
  'url',
  'text',
  'error',
  'video',
  'audio',
  'code',
  'markdown',
  'pdf',
  'html',
  'csv',
  'xlsx',
  'docx',
  'pptx',
] as const
type ShowType = (typeof TYPES)[number]

/** Display variants that control how the frontend renders the output. */
const VARIANTS = [
  'compact',   // Minimal inline card — small footprint in the conversation
  'full',      // Full available space — ideal for URL previews, HTML, PDFs
  'gallery',   // Visual-first — centers content with proper aspect ratio
  'detail',    // Rich layout — prominent title, description, content sections
] as const
type ShowVariant = (typeof VARIANTS)[number]

/** Aspect ratio presets for visual content. */
const ASPECT_RATIOS = [
  'auto',
  '1:1',
  '16:9',
  '9:16',
  '4:3',
  '3:2',
  '21:9',
] as const
type ShowAspectRatio = (typeof ASPECT_RATIOS)[number]

/** Visual theme for the output card. */
const THEMES = [
  'default',
  'success',
  'warning',
  'info',
  'danger',
] as const
type ShowTheme = (typeof THEMES)[number]

interface ShowEntry {
  id: string
  timestamp: string
  type: ShowType
  title?: string
  description?: string
  path?: string
  url?: string
  content?: string
  variant?: ShowVariant
  aspect_ratio?: ShowAspectRatio
  theme?: ShowTheme
  language?: string
  metadata?: Record<string, unknown>
}

function generateId(): string {
  return `show_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`
}

/** Infer a sensible default variant based on content type. */
function defaultVariant(type: ShowType): ShowVariant {
  switch (type) {
    case 'url':
    case 'html':
    case 'pdf':
      return 'full'
    case 'image':
    case 'video':
      return 'gallery'
    case 'code':
    case 'markdown':
    case 'text':
      return 'detail'
    case 'csv':
    case 'xlsx':
      return 'full'
    case 'docx':
    case 'pptx':
      return 'full'
    case 'audio':
    case 'file':
      return 'compact'
    case 'error':
      return 'compact'
    default:
      return 'detail'
  }
}

// ── Shared validation ──────────────────────────────────────────────────────

const PATH_TYPES: ShowType[] = ['file', 'image', 'video', 'audio', 'pdf', 'csv', 'xlsx', 'docx', 'pptx']
const CONTENT_TYPES: ShowType[] = ['text', 'error', 'code', 'markdown', 'html']

function validateAndBuildEntry(item: Record<string, unknown>, dir: string): string | ShowEntry {
  const type = item.type as ShowType | undefined
  if (!type || !TYPES.includes(type as ShowType)) {
    return `'type' is required. Use one of: ${TYPES.join(', ')}.`
  }

  if (PATH_TYPES.includes(type) && !item.path) {
    return `'path' is required when type is '${type}'.`
  }
  if (type === 'url' && !item.url) {
    return `'url' is required when type is 'url'.`
  }
  if (CONTENT_TYPES.includes(type) && !item.content) {
    return `'content' is required when type is '${type}'.`
  }

  if (PATH_TYPES.includes(type) && item.path) {
    const absPath = resolve(dir, item.path as string)
    if (!existsSync(absPath)) {
      return `File not found: ${absPath}`
    }
  }

  const variant = (item.variant as ShowVariant) || undefined
  if (variant && !VARIANTS.includes(variant)) {
    return `Invalid variant '${variant}'. Use one of: ${VARIANTS.join(', ')}.`
  }

  const aspectRatio = (item.aspect_ratio as ShowAspectRatio) || undefined
  if (aspectRatio && !ASPECT_RATIOS.includes(aspectRatio)) {
    return `Invalid aspect_ratio '${aspectRatio}'. Use one of: ${ASPECT_RATIOS.join(', ')}.`
  }

  const theme = (item.theme as ShowTheme) || undefined
  if (theme && !THEMES.includes(theme)) {
    return `Invalid theme '${theme}'. Use one of: ${THEMES.join(', ')}.`
  }

  let metadata: Record<string, unknown> | undefined
  if (item.metadata) {
    if (typeof item.metadata === 'string') {
      try {
        metadata = JSON.parse(item.metadata)
      } catch {
        return `Invalid JSON in 'metadata' parameter.`
      }
    } else if (typeof item.metadata === 'object') {
      metadata = item.metadata as Record<string, unknown>
    }
  }

  const resolvedVariant = variant || defaultVariant(type)

  return {
    id: generateId(),
    timestamp: new Date().toISOString(),
    type,
    variant: resolvedVariant,
    ...(item.title ? { title: item.title as string } : {}),
    ...(item.description ? { description: item.description as string } : {}),
    ...(item.path ? { path: resolve(dir, item.path as string) } : {}),
    ...(item.url ? { url: item.url as string } : {}),
    ...(item.content ? { content: item.content as string } : {}),
    ...(aspectRatio ? { aspect_ratio: aspectRatio } : {}),
    ...(theme && theme !== 'default' ? { theme } : {}),
    ...(item.language ? { language: item.language as string } : {}),
    ...(metadata ? { metadata } : {}),
  }
}

// ── Tool definition ────────────────────────────────────────────────────────

const SERVE_EXAMPLE = '`nohup python3 -m http.server 3000 --directory /workspace/site >/tmp/site.log 2>&1 &`'

const showParameters = {
  type: 'object',
  properties: {
    action: { type: 'string', description: "Action: 'show' to present an item to the user." },
    type: {
      type: 'string',
      description:
        "Type of item. Required for single-item 'show' (omit when using 'items'). " +
        "Options: 'file' (any file on disk), 'image' (image file), 'url' (web link or localhost preview), " +
        "'text' (inline text), 'error' (error message), 'video' (video file), 'audio' (audio file), " +
        "'code' (syntax-highlighted code block), 'markdown' (rendered markdown), " +
        "'pdf' (PDF document), 'html' (raw HTML rendered in sandboxed iframe), " +
        "'csv' (CSV/TSV tabular data), 'xlsx' (Excel spreadsheet), " +
        "'docx' (Word document), 'pptx' (PowerPoint presentation).",
    },
    title: { type: 'string', description: "Short heading. E.g. 'Generated Logo', 'API Response', 'Build Output'." },
    description: { type: 'string', description: "Longer description shown below the title. E.g. 'A 1024x1024 logo in your brand colors'." },
    path: {
      type: 'string',
      description:
        "Absolute file path. Required when type is 'file', 'image', 'video', 'audio', 'pdf', 'csv', 'xlsx', 'docx', or 'pptx'. " +
        "E.g. '/workspace/output/logo.png'. Note: passing a .html path as type='file' does not host/execute it; " +
        `serve it with a local web server (e.g. ${SERVE_EXAMPLE} with bash) and pass its ` +
        "plain http://localhost:PORT/ URL as type='url' for live HTML pages.",
    },
    url: {
      type: 'string',
      description:
        "URL to show. Required when type is 'url'. Use for localhost previews (e.g. 'http://localhost:3000') " +
        'or external links. For standalone HTML files, first serve them via a web server, then pass the served URL here.',
    },
    content: {
      type: 'string',
      description:
        "Inline content for display. Required when type is 'text', 'error', 'code', 'markdown', or 'html'. " +
        'Use this to communicate information briefly — not to author full artifacts from scratch. ' +
        "If the content is a new document you're creating (spec, report, plan, etc.), write it to a file first and use type='file' with path. " +
        "For 'html', inline HTML rendered in a sandboxed iframe (not a file path).",
    },
    variant: {
      type: 'string',
      description:
        'Display variant controlling the layout. Options: ' +
        "'compact' (minimal inline card), 'full' (fills available space — great for previews), " +
        "'gallery' (visual-first, centered with aspect ratio — great for images/video), " +
        "'detail' (rich layout with prominent title, description, content). " +
        'Smart defaults per type if omitted.',
    },
    aspect_ratio: {
      type: 'string',
      description:
        "Aspect ratio for visual content. Options: 'auto' (default), '1:1', '16:9', '9:16', '4:3', '3:2', '21:9'. " +
        "Most useful with type='image' or type='video' + variant='gallery'.",
    },
    theme: {
      type: 'string',
      description:
        "Visual accent theme. Options: 'default', 'success' (green), 'warning' (amber), " +
        "'info' (blue), 'danger' (red). Affects the border/badge colors.",
    },
    language: {
      type: 'string',
      description: "Programming language for syntax highlighting. Only used when type='code'. " + "E.g. 'python', 'typescript', 'rust', 'json', 'bash'.",
    },
    metadata: { type: 'string', description: 'Optional JSON string of extra metadata. E.g. \'{"width":1024,"format":"png","duration":"3:42"}\'.' },
    items: {
      type: 'string',
      description:
        'JSON array of items to show as a carousel. Each item is an object with: ' +
        'type (required), title, description, path, url, content, variant, aspect_ratio, theme, language, metadata. ' +
        'When provided, individual type/path/url/content params are ignored. ' +
        'Example: \'[{"type":"image","title":"Logo v1","path":"/workspace/v1.png"},{"type":"image","title":"Logo v2","path":"/workspace/v2.png"}]\'',
    },
  },
  required: ['action'],
}

const shown = (value: unknown) => JSON.stringify(value, null, 2)

/** A relative `path` resolves against the project checkout (`context.directory`). */
export default {
  description:
    'Show outputs and attachments to the human user. This tool PRESENTS and DISPLAYS existing content — ' +
    'it is NOT a place to author or store artifacts. Show should SHOW, not be where you write.\n\n' +
    'CRITICAL RULE: Do not use show to write new artifacts from scratch. If you need to create a ' +
    'spec, report, plan, document, config, or any authored content — write it to a file first ' +
    "using the write tool, then present it with show(type='file', path='...'). " +
    "The 'content' parameter is for communicating brief information inline (status, summaries, " +
    'snippets, errors, previews) — not for authoring documents.\n\n' +
    "Good: Write spec to /workspace/spec.md → show(type='file', path='/workspace/spec.md')\n" +
    "Good: show(type='text', content='Build succeeded in 3.2s')\n" +
    "Good: show(type='code', content='const x = 1;', language='typescript')\n" +
    "Bad: show(type='markdown', content='# Full spec written from scratch here...') — write to file first!\n\n" +
    'Types: file, image, url, text, error, video, audio, code, markdown, pdf, html, csv, xlsx, docx, pptx.\n' +
    "IMPORTANT HTML NOTE: type='html' renders INLINE HTML from the 'content' field only. " +
    'A standalone .html file or website on disk is NOT auto-hosted — serve it with a local web server, ' +
    "then pass its plain URL with type='url'. For a static site, start one in the background with bash " +
    `(e.g. ${SERVE_EXAMPLE}); for an app, run its dev server the same way ` +
    "(e.g. `npm run dev`). Then show(type='url', url='http://localhost:3000/'). The platform auto-detects " +
    'and proxies any localhost port — just use a plain http://localhost:PORT/ URL, no special path format needed.\n' +
    'Variants (display hints): compact, full, gallery, detail — controls layout. ' +
    'Defaults are smart per type but can be overridden.\n' +
    'aspect_ratio: auto, 1:1, 16:9, 9:16, 4:3, 3:2, 21:9 — for visual content.\n' +
    'theme: default, success, warning, info, danger — visual accent.\n' +
    "language: for type='code', the language for syntax highlighting (e.g. 'python', 'typescript').\n\n" +
    'MULTI-ITEM MODE: To show multiple items at once (rendered as a carousel), pass a JSON array ' +
    "string to the 'items' parameter instead of individual type/path/url/content params. " +
    'Each item in the array is an object with the same fields (type, title, path, url, content, etc.).\n' +
    'When you have 2 or more outputs to present together (several screenshots, a page and its docs, ' +
    "v1 and v2 of a design), make ONE show call with 'items' — not one show call per output. " +
    'Give each item its own title so the user can tell them apart while paging.',
  parameters: showParameters,
  async execute(args: Record<string, any>, { directory: dir }: ToolContext): Promise<string> {
    if (args.items) {
      let parsed: unknown
      try {
        parsed = JSON.parse(args.items)
      } catch {
        throw new Error("Invalid JSON in 'items' parameter. Must be a JSON array of objects.")
      }
      if (!Array.isArray(parsed) || parsed.length === 0) throw new Error("'items' must be a non-empty JSON array.")
      const entries: ShowEntry[] = []
      const errors: string[] = []
      parsed.forEach((item, i) => {
        const result = item && typeof item === 'object' ? validateAndBuildEntry(item as Record<string, unknown>, dir) : 'must be an object.'
        if (typeof result === 'string') errors.push(`Item ${i}: ${result}`)
        else entries.push(result)
      })
      if (entries.length === 0) throw new Error(`All items failed validation:\n${errors.join('\n')}`)
      return shown({
        success: true,
        action: 'show',
        ...(args.title && { title: args.title }),
        ...(args.description && { description: args.description }),
        ...(args.theme && args.theme !== 'default' && { theme: args.theme }),
        items: entries,
        ...(errors.length > 0 && { warnings: errors }),
        message: `${entries.length} item(s) presented to user as carousel.`,
      })
    }
    const entry = validateAndBuildEntry(args, dir)
    if (typeof entry === 'string') throw new Error(entry)
    return shown({ success: true, action: 'show', entry, message: `Item '${args.title || args.type}' presented to user.` })
  },
}

web_search:
/**
 * web_search: the Kortix web search tool (Tavily). Kortix maintains this file.
 * A project lists it in kortix.yaml as `web_search: kortix:web_search`.
 * `kortix tools eject web_search` copies it to `tools/web_search.ts` for the
 * project to own and change; the copy runs unchanged on every harness.
 *
 * A call goes to the Kortix API's billed router proxy with the session token
 * (`KORTIX_API_URL`, `KORTIX_TOKEN`); the router holds the Tavily key. A box
 * with no Kortix API calls Tavily itself with `TAVILY_API_KEY`.
 *
 * The web UI renders a call from the output JSON. A changed copy must keep
 * that shape, or the UI shows the raw output.
 */

/** What a call receives (the project tool contract): the session env, secrets included, and the turn's abort signal. */
interface ToolContext {
  env: Record<string, string | undefined>
  signal?: AbortSignal
}

const TIMEOUT_MS = 60_000

/** The Kortix router proxy and the session token, or Tavily and the project's own key. */
function upstream(env: ToolContext['env']): { base: string; key: string } {
  const api = env.KORTIX_API_URL?.trim().replace(/\/+$/, '')
  if (api) {
    const token = env.KORTIX_TOKEN?.trim()
    if (!token) throw new Error('KORTIX_TOKEN is not set.')
    return { base: `${api.endsWith('/v1') ? api : `${api}/v1`}/router/tavily`, key: token }
  }
  const key = env.TAVILY_API_KEY?.trim()
  if (!key) throw new Error('TAVILY_API_KEY is not set.')
  return { base: 'https://api.tavily.com', key }
}

type TavilyResponse = {
  answer?: string
  results?: Array<{ title?: string; url?: string; content?: string; score?: number; published_date?: string }>
  images?: Array<string | { url?: string; description?: string }>
  response_time?: number
}

export default {
  description:
    'Search the web for up-to-date information using Tavily. ' +
    'Returns titles, URLs, snippets, relevance scores, images, and a synthesized AI answer. ' +
    'Supports batch queries separated by |||. ' +
    "Use topic='news' for current events, topic='finance' for financial data. " +
    'After using results, ALWAYS include a Sources section with markdown hyperlinks.',
  parameters: {
    type: 'object',
    properties: {
      query: { type: 'string', description: "Search query. For batch, separate with ||| (e.g. 'query one ||| query two')" },
      num_results: { type: 'number', description: 'Results per query (1-20). Default: 5' },
      topic: { type: 'string', description: "Search topic: 'general' (default), 'news', or 'finance'" },
      search_depth: {
        type: 'string',
        description:
          "Search depth: 'basic' (faster, cheaper, default) or 'advanced' (slower, more thorough). Use 'basic' for most queries. Reserve 'advanced' for deep research where comprehensiveness matters.",
      },
    },
    required: ['query'],
  },
  async execute(args: Record<string, any>, { env, signal }: ToolContext): Promise<string> {
    const { base, key } = upstream(env)
    const queries = String(args.query ?? '').split('|||').map((query) => query.trim()).filter(Boolean)
    if (queries.length === 0) throw new Error('The query is empty.')
    const timeout = signal ? AbortSignal.any([signal, AbortSignal.timeout(TIMEOUT_MS)]) : AbortSignal.timeout(TIMEOUT_MS)
    const searchOne = async (query: string) => {
      try {
        const response = await fetch(`${base}/search`, {
          method: 'POST',
          headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
          body: JSON.stringify({
            query,
            search_depth: args.search_depth || 'basic',
            topic: args.topic || 'general',
            max_results: Math.max(1, Math.min(args.num_results ?? 5, 20)),
            include_answer: true,
            include_images: true,
            include_image_descriptions: true,
          }),
          signal: timeout,
        })
        const body = await response.text()
        if (!response.ok) throw new Error(`${response.status} Error: ${body}`)
        const data = JSON.parse(body) as TavilyResponse
        const results = data.results ?? []
        return {
          query,
          success: results.length > 0 || !!data.answer,
          answer: data.answer ?? '',
          results: results.map((r) => ({
            title: r.title ?? '',
            url: r.url ?? '',
            snippet: r.content ?? '',
            score: r.score ?? 0,
            published_date: r.published_date ?? '',
          })),
          images: (data.images ?? []).map((image) =>
            typeof image === 'string' ? { url: image, description: '' } : { url: image.url ?? '', description: image.description ?? '' },
          ),
          response_time_ms: data.response_time,
        }
      } catch (err) {
        return { query, success: false, error: String(err) }
      }
    }
    const results = await Promise.all(queries.map(searchOne))
    if (results.length === 1) return JSON.stringify(results[0], null, 2)
    return JSON.stringify({ batch_mode: true, total_queries: queries.length, results }, null, 2)
  },
}
